bin/rails runner -e test '
ActiveRecord::FixtureSet.create_fixtures(Rails.root.join("test/fixtures"), %w[users books leaves accesses pages sections pictures])

book = Book.find_by(slug: "handbook")
Current.user = User.find_by(email_address: "kevin@example.com")
leaves = book.leaves.active.with_leafables.positioned.to_a

ActiveRecord::Base.logger = Logger.new(STDOUT)

puts "--- Testing cached proc key generation ---"
key_proc1 = ->(leaf) { [ leaf, leaf.book, leaf.book.editable? ] }
leaves.each { |l| key_proc1.call(l) }

puts "--- Testing with @book ---"
@book = book
key_proc2 = ->(leaf) { [ leaf, @book, @book.editable? ] }
leaves.each { |l| key_proc2.call(l) }

puts "--- Testing with leaf, leaf.book ---"
leaves.each { |l| [ l, l.book, @book.editable? ] }
'

